# Load demos
with open(d + '/task-77262100.json') as f:
    demos = json.load(f)

def solve_task77262100(grid):
    """
    Rule: shape shifts horizontally to sit flush against vertical color-2 line
    (same side, same rows); old shape area becomes background; 
    full-height color-8 line drawn at shape's old rightmost column
    """
    inp = json.loads(json.dumps(grid))
    bg = inp[0][0]
    h, w = len(inp), len(inp[0])

    # Find color-2 vertical line
    col_2 = None
    for c in range(w):
        if inp[0][c] == 2:
            is_vertical = all(inp[r][c] == 2 for r in range(h) if inp[r][c] != bg)
            if is_vertical:
                col_2 = c
                break

    # Find shape
    shape_rows = set()
    shape_cols = set()
    for r in range(h):
        for c in range(w):
            if inp[r][c] != bg and inp[r][c] != 2:
                shape_rows.add(r)
                shape_cols.add(c)

    min_r, max_r = min(shape_rows), max(shape_rows)
    min_c, max_c = min(shape_cols), max(shape_cols)

    # Distance from shape to line
    distance = max_c - col_2
    shift = distance - 1  # Shape rightmost col should be at col_2 + 1

    # Build result
    result = [[bg]*w for _ in range(h)]

    # Copy line 2
    for r in range(h):
        result[r][col_2] = 2

    # Place 8 at old shape rightmost column (full height)
    for r in range(h):
        result[r][max_c] = 8

    # Place shape (non-bg cells) shifted
    for r in range(h):
        for c in range(w):
            if inp[r][c] != bg and inp[r][c] != 2:
                new_c = c - shift
                if 0 <= new_c < w:
                    result[r][new_c] = inp[r][c]

    return result

# Test on Demo 0
d0_in = demos[0]['input']
d0_out = demos[0]['output']
d0_pred = solve_task77262100(d0_in)

def grids_match(g1, g2):
    if len(g1) != len(g2) or len(g1[0]) != len(g2[0]):
        return False
    return all(g1[r][c] == g2[r][c] for r in range(len(g1)) for c in range(len(g1[0])))

print(f"Demo 0 match: {grids_match(d0_pred, d0_out)}")

if not grids_match(d0_pred, d0_out):
    print("\nDemo 0 diff:")
    for r in range(len(d0_pred)):
        for c in range(len(d0_pred[0])):
            if d0_pred[r][c] != d0_out[r][c]:
                print(f"  ({r},{c}): pred={d0_pred[r][c]}, actual={d0_out[r][c]}")

